import {
  SidebarInset,
  SidebarProvider,
  SidebarTrigger,
} from "@/components/ui/sidebar";
import { AppSidebar } from "@/components/sidebar-14/app-sidebar";

export default function Sidebar14Page() {
  return (
    <SidebarProvider>
      <SidebarInset>
        <header className="flex h-14 shrink-0 items-center gap-2 border-b px-4">
          <div className="min-w-0">
            <p className="truncate font-medium text-sm">Data fetching</p>
            <p className="truncate text-muted-foreground text-xs">
              Build your application
            </p>
          </div>
          <SidebarTrigger className="ms-auto rotate-180 rtl:rotate-0" />
        </header>
        <main className="flex flex-1 flex-col gap-4 p-4">
          <div className="grid gap-4 md:grid-cols-3">
            {["routing", "caching", "rendering"].map((card) => (
              <div className="aspect-video rounded-xl bg-muted/45" key={card} />
            ))}
          </div>
          <div className="min-h-96 flex-1 rounded-xl bg-muted/45" />
        </main>
      </SidebarInset>
      <AppSidebar />
    </SidebarProvider>
  );
}

"use client";

import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarMenuSub,
  SidebarMenuSubButton,
  SidebarMenuSubItem,
  SidebarRail,
} from "@/components/ui/sidebar";

const tableOfContents = [
  { items: ["Installation", "Project structure"], label: "Getting started" },
  {
    items: ["Routing", "Data fetching", "Rendering", "Caching", "Styling"],
    label: "Build your application",
  },
  {
    items: ["Components", "File conventions", "Functions"],
    label: "API reference",
  },
  { items: ["Accessibility", "Fast refresh"], label: "Architecture" },
];

export function AppSidebar() {
  return (
    <Sidebar placement="right">
      <SidebarContent>
        <SidebarGroup>
          <SidebarGroupLabel>Table of contents</SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {tableOfContents.map((section) => (
                <SidebarMenuItem key={section.label}>
                  <SidebarMenuButton asChild>
                    <a className="font-medium" href="#">
                      {section.label}
                    </a>
                  </SidebarMenuButton>
                  <SidebarMenuSub>
                    {section.items.map((item) => (
                      <SidebarMenuSubItem key={item}>
                        <SidebarMenuSubButton
                          asChild
                          isActive={item === "Data fetching"}
                        >
                          <a href="#">{item}</a>
                        </SidebarMenuSubButton>
                      </SidebarMenuSubItem>
                    ))}
                  </SidebarMenuSub>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>
      <SidebarRail />
    </Sidebar>
  );
}
